// The HTTP node returns raw text (SSE format). Extract JSON-RPC payload.
var rawText = $input.first().json;
if (typeof rawText === 'object') { rawText = JSON.stringify(rawText); }
var jsonStr = rawText;
var dataMatch = rawText.match(/^data:\s*(.+)$/m);
if (dataMatch) { jsonStr = dataMatch[1]; } else { var m = rawText.match(/\{[\s\S]*\}/); if (m) jsonStr = m[0]; }

var httpResponse;
try { httpResponse = JSON.parse(jsonStr); } catch(e) { throw new Error('Failed to parse SSE response: ' + rawText.substring(0, 300)); }

if (httpResponse.error) { throw new Error('MCP Error: ' + (httpResponse.error.message || JSON.stringify(httpResponse.error))); }

var result = httpResponse.result;
if (!result || !result.content || !result.content[0]) { throw new Error('Bad MCP response: ' + JSON.stringify(httpResponse).substring(0, 300)); }

var textContent = result.content[0].text;
var toolResult;
try { toolResult = JSON.parse(textContent); } catch(e) { return { raw_response: textContent, error: 'Could not parse tool result' }; }

var rows = toolResult.rows || [];

return {
  rows: rows,
  row_count: toolResult.row_count || 0,
  page: toolResult.page || 1,
  nextCursor: toolResult.nextCursor || null,
  truncated: toolResult.truncated || false,
  query: toolResult.query || '',
  database: toolResult.database || '',
  accumulated_rows: rows,
  pages_fetched: 1
};

