// Only the current page is parsed here; accumulation happens in "Merge Page Into Accumulator".
var rawText = $input.first().json;
if (typeof rawText === 'object') { rawText = JSON.stringify(rawText); }
var jsonStr = rawText;
var dataMatch = rawText.match(/^data:\s*(.+)$/m);
if (dataMatch) { jsonStr = dataMatch[1]; } else { var m = rawText.match(/\{[\s\S]*\}/); if (m) jsonStr = m[0]; }

var httpResponse = JSON.parse(jsonStr);
if (httpResponse.error) { throw new Error('MCP Error on page: ' + httpResponse.error.message); }

var result = httpResponse.result;
var textContent = result.content[0].text;
var toolResult = JSON.parse(textContent);

return {
  rows: toolResult.rows || [],
  row_count: toolResult.row_count || 0,
  page: toolResult.page || 1,
  nextCursor: toolResult.nextCursor || null,
  truncated: toolResult.truncated || false,
  database: toolResult.database || '',
  query: toolResult.query || ''
};

// Carries the running accumulator forward instead of relying on $input.all() at loop end.
var prior = $('Check Need More Pages').item.json;
var current = $input.first().json;

var priorRows = prior.accumulated_rows || [];
var mergedRows = priorRows.concat(current.rows || []);
var pagesFetched = (prior.pages_fetched || 1) + 1;

var maxPages = $('Set Query Params').item.json.max_pages || 1000;
if (pagesFetched > maxPages) {
  throw new Error('Pagination guard exceeded: fetched ' + pagesFetched + ' pages, max_pages=' + maxPages);
}

return {
  accumulated_rows: mergedRows,
  row_count: mergedRows.length,
  pages_fetched: pagesFetched,
  nextCursor: current.nextCursor || null,
  truncated: current.truncated || false,
  database: prior.database || '',
  query: prior.query || ''
};

// The incoming item already holds the fully aggregated result; no $input.all() needed.
var item = $input.first().json;
var rows = item.accumulated_rows || [];

return {
  rows: rows,
  row_count: rows.length,
  pages_fetched: item.pages_fetched || 1,
  database: item.database || '',
  query: item.query || ''
};
